import { httpResource } from '@angular/common/http';
import { Component, signal } from '@angular/core';

@Component({
  selector: 'app-profile-form',
  template: `<input [value]="draft().bio" (input)="edit($event)" />`,
})
export class ProfileForm {
  readonly draft = signal<Profile>({ name: '', bio: '' });

  // Sends a PUT on creation with the empty draft, then one per
  // keystroke; each new PUT cancels the one still pending
  readonly save = httpResource<Profile>(() => ({
    url: '/api/profile',
    method: 'PUT',
    body: this.draft(),
  }));

  edit(event: Event) {
    const bio = (event.target as HTMLInputElement).value;
    this.draft.update((d) => ({ ...d, bio }));
  }
}

import { HttpClient, httpResource } from '@angular/common/http';
import { Component, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

@Component({
  selector: 'app-profile-form',
  template: `<button (click)="save()" [disabled]="saving()">Save</button>`,
})
export class ProfileForm {
  private readonly http = inject(HttpClient);
  // Reading: one GET when created; reload() fetches it again
  readonly profile = httpResource<Profile>(() => '/api/profile');
  readonly draft = signal<Profile>({ name: '', bio: '' });
  readonly saving = signal(false);
  // Writing: one PUT per click, sent now, and nothing cancels it
  async save() {
    this.saving.set(true);
    try {
      const req = this.http.put<Profile>('/api/profile', this.draft());
      this.profile.set(await firstValueFrom(req)); // status(): 'local'
    } finally {
      this.saving.set(false);
    }
  }
}
